import random, itertools

unit='((..(..((....))..(((.(..(.(((...)))..)..)..)))..(..(....)..).(..(....)..).....((....))..)..))'

# find pairs
pairs=[]
stack=[]
for i,c in enumerate(unit):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs.append((j,i))

def comp(c):
    return {'A':'U','U':'A','G':'C','C':'G'}[c]

pair_types=['GC','CG','AU','UA','GU','UG']

def build(pair_assignment):
    seq=['A']*len(unit)
    for (a,b),pt in zip(pairs, pair_assignment):
        seq[a]=pt[0]; seq[b]=comp(pt[0])
    # loops: position is '.' -> use A but vary
    for i,c in enumerate(unit):
        if c=='.':
            seq[i]='A'
    return ''.join(seq)

# Generate random candidates
random.seed(0)
cands=[]
for _ in range(2000):
    pa=[random.choice(pair_types) for _ in pairs]
    s=build(pa)
    # add some variation in loops: replace some A with U randomly in loop regions to avoid long A runs causing alt structures
    cands.append(s)

# print first 5 to inspect
for s in cands[:3]:
    print(s)
print(len(cands))
EOF
